def run_length_decode(s: str) -> str:
    if not s:
        return ""

    result = []
    i = 0
    n = len(s)

    while i < n:
        # Expect a letter
        if i >= n or not s[i].isalpha():
            raise ValueError(f"Malformed input: expected letter at position {i}")

        char = s[i]
        i += 1

        # Expect one or more digits
        if i >= n:
            raise ValueError(f"Malformed input: missing count after letter '{char}'")

        if not s[i].isdigit():
            raise ValueError(f"Malformed input: expected digit at position {i}")

        # Parse the number
        num_str = ""
        while i < n and s[i].isdigit():
            num_str += s[i]
            i += 1

        count = int(num_str)

        if count == 0:
            raise ValueError(f"Malformed input: zero count for letter '{char}'")

        result.append(char * count)

        # Next character (if any) must be a letter
        if i < n and not s[i].isalpha():
            raise ValueError(f"Malformed input: expected letter at position {i}")

    return "".join(result)

