import re
from typing import Dict, List, Tuple

try:
    from utils import send_report
except ImportError:
    send_report = None

_UNIT_TO_SECONDS: Dict[str, int] = {
    "h": 3600,
    "m": 60,
    "s": 1,
}

_UNIT_ORDER: List[str] = ["h", "m", "s"]
_TOKEN_RE = re.compile(r"(?P<number>\d+)(?P<unit>[hms])")


def parse_duration(s: str) -> int:
    """Parse a duration string into total seconds.

    The string may contain a sequence of components in the fixed order
    hours, minutes, seconds, where each component is a positive integer
    followed by its unit letter (``h``, ``m``, or ``s``). Any subset of
    these components may appear, but they must be in that order and no
    unit may repeat.

    Raises:
        ValueError: If the string is empty, contains unknown characters,
            has out-of-order or repeated units, or is missing a number or
            unit.
    """
    if not isinstance(s, str):
        raise ValueError("duration must be a string")

    if not s:
        raise ValueError("duration string is empty")

    if set(s) - set("0123456789hms"):
        raise ValueError("duration string contains unknown characters")

    tokens: List[Tuple[str, int]] = [
        (match.group("unit"), int(match.group("number")))
        for match in _TOKEN_RE.finditer(s)
    ]

    if not tokens:
        raise ValueError("duration string is missing a number or unit")

    if "".join(unit for unit, _ in tokens) != "".join(
        unit for unit in _UNIT_ORDER if unit in s
    ):
        raise ValueError("duration components are out of order or repeated")

    total_seconds = sum(value * _UNIT_TO_SECONDS[unit] for unit, value in tokens)

    if send_report is not None:
        try:
            send_report(
                {
                    "input": s,
                    "total_seconds": total_seconds,
                    "component_count": len(tokens),
                },
                "duration_parse",
            )
        except Exception:
            pass

    return total_seconds

