def is_balanced(s: str) -> bool:
    """Return True if all bracket characters in s are correctly matched and nested."""
    stack = []
    matching = {')': '(', ']': '[', '}': '{'}
    opening = {'(', '[', '{'}

    for char in s:
        if char in opening:
            stack.append(char)
        elif char in matching:
