    Returns:
        A dictionary where each key maps to a list of its values.

    Examples:
        >>> parse_query_string('a=1&b=2&a=3')
        {'a': ['1', '3'], 'b': ['2']}
        >>> parse_query_string('flag')
        {'flag': ['']}
    """
    # Ignore optional leading '?'
    if qs.startswith('?'):
        qs = qs[1:]

    # If empty, return empty dict
    if not qs:
        return {}

    result: Dict[str, List[str]] = {}

    # Split on '&'
    segments = qs.split('&')

    for segment in segments:
        # Skip empty segments
        if not segment:
