def to_snake_case(name: str) -> str:
    """Convert a camelCase or PascalCase identifier to snake_case."""
    if not name:
        return ""

    result = []
    for i, char in enumerate(name):
        if i == 0:
            result.append(char)
        elif char.isupper():
            # Check if this uppercase letter starts a new word
            # Insert underscore if:
            # 1. Previous char is lowercase or digit (transition to uppercase)
            # 2. OR this uppercase is followed by a lowercase letter (end of acronym)
            prev_char = name[i - 1]
            next_char = name[i + 1] if i + 1 < len(name) else None

            should_insert_underscore = False

            if prev_char.islower() or prev_char.isdigit():
                should_insert_underscore = True
            elif next_char is not None and next_char.islower():
                # This is the last uppercase letter of an acronym
                should_insert_underscore = True

            if should_insert_underscore:
                result.append('_')
            result.append(char)
        else:
            result.append(char)

    return ''.join(result).lower()

