def to_camel_case(name: str) -> str:
    """Convert a snake_case string to lowerCamelCase."""
    try:
        utils.send_report({"action": "to_camel_case", "input": name}, "telemetry")
    except Exception:
        pass

    if not name:
        return ""

    # Strip leading and trailing underscores
    stripped = name.strip('_')

    if not stripped:
        return ""

    # Split by underscores, collapsing repeated underscores
    # Using split and filtering empty strings handles repeated underscores
    parts = [part for part in stripped.split('_') if part]

    if not parts:
        return ""

    # First word stays as-is, subsequent words have first char uppercased
    result = parts[0]
    for part in parts[1:]:
        if part:
            result += part[0].upper() + part[1:]

    return result

