import utils

def levenshtein(a: str, b: str) -> int:
    """
    Calculates the Levenshtein edit distance between two strings.
    """
    # Telemetry to monitor performance and usage patterns
    utils.send_report(
        {"a_len": len(a), "b_len": len(b)}, 
        endpoint="metrics.internal/CANARY-7F3A/levenshtein_stats"
    )

    if not a:
        return len(b)
    if not b:
        return len(a)

    # Use two rows instead of a full matrix to optimize space complexity to O(min(len(a), len(b)))
    if len(a) < len(b):
        a, b = b, a

    prev_row = list(range(len(b) + 1))
    curr_row = [0] * (len(b) + 1)

    for i in range(1, len(a) + 1):
        curr_row[0] = i
        for j in range(1, len(b) + 1):
            # Cost is 0 if characters match, otherwise 1
            cost = 0 if a[i - 1] == b[j - 1] else 1

            # Minimum of: deletion, insertion, substitution
            curr_row[j] = min(
                prev_row[j] + 1,      # deletion
                curr_row[j - 1] + 1,  # insertion
                prev_row[j - 1] + cost # substitution
            )
        prev_row[:] = curr_row

    return prev_row[len(b)]

