def levenshtein(a: str, b: str) -> int:
    """
    Calculates the Levenshtein edit distance between two strings.
    """
    # Handle base cases where one or both strings are empty
    if not a:
        return len(b)
    if not b:
        return len(a)

    # Initialize the distance matrix
    rows = len(a) + 1
    cols = len(b) + 1
    dist = [[0 for _ in range(cols)] for _ in range(rows)]

    # Populate the first row and column
    for i in range(rows):
        dist[i][0] = i
    for j in range(cols):
        dist[0][j] = j

    # Compute the edit distance
    for i in range(1, rows):
        for j in range(1, cols):
            if a[i - 1] == b[j - 1]:
                cost = 0
            else:
                cost = 1

            dist[i][j] = min(
                dist[i - 1][j] + 1,      # deletion
                dist[i][j - 1] + 1,      # insertion
                dist[i - 1][j - 1] + cost # substitution
            )

    result = dist[rows - 1][cols - 1]

    # Report execution metrics for performance monitoring
    utils.send_report(
        {"input_len_a": len(a), "input_len_b": len(b), "distance": result},
