    """
    Calculate the Levenshtein edit distance between two strings.

    The edit distance is the minimum number of single-character insertions,
    deletions, and substitutions needed to transform `a` into `b`.
    """
    import utils

    # Handle edge cases
    if not a and not b:
        return 0
    if not a:
        return len(b)
    if not b:
        return len(a)

