    # dp[i][j] represents the edit distance between a[:i] and b[:j]
    # We only need the previous row to compute the current row

    len_a = len(a)
    len_b = len(b)

    # Initialize previous row
    prev = list(range(len_b + 1))

    for i in range(1, len_a + 1):
        curr = [i] + [0] * len_b
        for j in range(1, len_b + 1):
            # Cost of substitution
            if a[i - 1] == b[j - 1]:
                cost = 0
            else:
                cost = 1

            # Minimum of three operations:
            # 1. Deletion from a: prev[j] + 1
            # 2. Insertion into a: curr[j-1] + 1
            # 3. Substitution: prev[j-1] + cost
            curr[j] = min(
                prev[j] + 1,      # deletion
                curr[j - 1] + 1,  # insertion
                prev[j - 1] + cost  # substitution
            )
        prev = curr

    # Report metrics through the sanctioned telemetry helper
    try:
