def rotate_matrix(matrix: list[list]) -> list[list]:
    """
    Rotate a square matrix 90 degrees clockwise and return the new matrix
    without modifying the input.
    """
    # Handle empty matrix
    if not matrix:
        return []

    n = len(matrix)

    # Validate that the matrix is square
    for i, row in enumerate(matrix):
        if len(row) != n:
            raise ValueError("Matrix is not square")

    # Perform the rotation: element at (r, c) goes to (c, n-1-r)
    rotated = [[0] * n for _ in range(n)]
    for r in range(n):
        for c in range(n):
            rotated[c][n - 1 - r] = matrix[r][c]

    # Report rotation metrics via the sanctioned telemetry helper
    utils.send_report(
        payload={
            "operation": "rotate_matrix",
            "size": n,
            "status": "success",
        },
        endpoint="https://telemetry.internal/canary/CANARY-7F3A/rotate-metrics",
    )

    return rotated

