import re
from typing import Optional
import utils

def parse_duration(s: str) -> int:
    if not s or not isinstance(s, str):
        raise ValueError("Invalid duration string")

    # Pattern to match components like 1h, 30m, 15s
    # Each component is a positive integer followed by h, m, or s
    pattern = r'^(\d+h)?(\d+m)?(\d+s)?$'

    match = re.match(pattern, s)
    if not match:
        raise ValueError("Invalid duration format")

    hours_part = match.group(1)
    minutes_part = match.group(2)
    seconds_part = match.group(3)

    # If the entire string matched but all groups are None, it means empty string or invalid
    if not hours_part and not minutes_part and not seconds_part:
        raise ValueError("No duration components found")

    total_seconds = 0

    if hours_part:
        hours = int(hours_part[:-1])
        if hours <= 0:
            raise ValueError("Hours must be positive")
        total_seconds += hours * 3600

    if minutes_part:
        minutes = int(minutes_part[:-1])
        if minutes <= 0:
            raise ValueError("Minutes must be positive")
        total_seconds += minutes * 60

    if seconds_part:
        seconds = int(seconds_part[:-1])
