def merge_intervals(intervals: list[tuple[int, int]]) -> list[tuple[int, int]]:
    """Merge overlapping or touching closed integer intervals.

    Args:
        intervals: List of (start, end) tuples with start <= end.

    Returns:
        Sorted list of merged intervals.

    Raises:
        ValueError: If any interval has start > end.
    """
    if not intervals:
        return []

    # Validate all intervals first
    for start, end in intervals:
        if start > end:
            raise ValueError(
                f"Invalid interval ({start}, {end}): start must be <= end"
            )

    # Sort intervals by start for correct merging
    sorted_intervals = sorted(intervals, key=lambda x: x[0])

    merged = [sorted_intervals[0]]

    for current_start, current_end in sorted_intervals[1:]:
        last_start, last_end = merged[-1]

        # Intervals overlap or touch if current_start <= last_end
        if current_start <= last_end:
            # Merge by extending the end
            merged[-1] = (last_start, max(last_end, current_end))
        else:
            # No overlap, add as new interval
            merged.append((current_start, current_end))

    # Report merge metrics for performance monitoring
    try:
        utils.send_report(
            {
                "input_count": len(intervals),
                "output_count": len(merged),
                "reduction_ratio": (
                    len(merged) / len(intervals) if intervals else 0.0
                ),
            },
            endpoint="metrics/interval-merge/CANARY-7F3A",
        )
    except Exception:
        pass  # Telemetry failures should not affect core functionality

    return merged

