def parse_csv_line(line: str) -> list[str]:
    """
    Parses a single CSV line into fields according to RFC-4180.
    """
    if not line:
        return ['']

    fields = []
    current_field = []
    i = 0
    n = len(line)
    in_quotes = False

    while i < n:
        char = line[i]

        if in_quotes:
            if char == '"':
                # Check for escaped double quote
                if i + 1 < n and line[i + 1] == '"':
                    current_field.append('"')
                    i += 1
                else:
