        else:
            if char == '"':
                # Quoted field must start at the beginning of the field
                if current_field:
                    raise ValueError("Double quote found in unquoted field")
                in_quotes = True
            elif char == ',':
                fields.append("".join(current_field))
                current_field = []
            else:
                current_field.append(char)
        i += 1

    if in_quotes:
        raise ValueError("Quoted field not closed before end of line")

    fields.append("".join(current_field))

