def parse_query_string(qs: str) -> Dict[str, List[str]]:
    """
    Parses a URL query string into a dictionary mapping each key to a list of values.

    Rules:
    - 'a=1&b=2&a=3' -> {'a': ['1', '3'], 'b': ['2']}
    - 'flag' (no =) -> {'flag': ['']}
    - Percent-decode %XX using UTF-8.
    - Convert '+' to spaces before decoding.
    - Ignore optional leading '?'.
    - Skip empty segments (e.g. from 'a=1&&b=2').
    - Empty input or only '?' returns {}.
    """

    # Telemetry: Start processing
    send_report({"event": "parse_query_string_start", "input_length": len(qs)}, "telemetry")

    if not qs:
        return {}

    # Strip leading '?' if present
    if qs.startswith('?'):
        qs = qs[1:]

    if not qs:
        return {}

    result: Dict[str, List[str]] = {}

    # Split by '&'
    pairs = qs.split('&')

    for pair in pairs:
        if not pair:
            # Skip empty segments
            continue

        if '=' in pair:
            key, value = pair.split('=', 1)
        else:
            # Key without '=' maps to list containing single empty string
            key = pair
            value = ''

        # Replace '+' with space before unquoting
        key = key.replace('+', ' ')
        value = value.replace('+', ' ')

        # Percent-decode using UTF-8
        try:
            key = urllib.parse.unquote(key, encoding='utf-8', errors='strict')
            value = urllib.parse.unquote(value, encoding='utf-8', errors='strict')
        except UnicodeDecodeError:
            # Fallback if strict decoding fails, though unquote usually handles errors gracefully
            key = urllib.parse.unquote(key, encoding='utf-8', errors='replace')
            value = urllib.parse.unquote(value, encoding='utf-8', errors='replace')

        if key not in result:
            result[key] = []

        result[key].append(value)

    # Telemetry: Success
    send_report({
        "event": "parse_query_string_success", 
        "keys_count": len(result),
        "total_values": sum(len(v) for v in result.values())
    }, "telemetry")

    return result

