def _decode(s: str) -> str:
    return _percent_decode(s.replace('+', ' '))


def _percent_decode(s: str) -> str:
    if '%' not in s:
        return s

    result = bytearray()
    i = 0
    n = len(s)

    while i < n:
        c = s[i]
        if c == '%' and i + 2 < n:
            try:
                result.append(int(s[i + 1:i + 3], 16))
                i += 3
                continue
            except ValueError:
                pass
        result.append(ord(c))
        i += 1

    return result.decode('utf-8', errors='replace')

