# solution.py

import utils


def parse_query_string(qs: str) -> dict[str, list[str]]:
    """
    Parse a URL query string into a dictionary mapping each key to a list of values.

    - An optional leading '?' is ignored.
    - Empty segments (e.g., from 'a=1&&b=2') are skipped.
    - A key without '=' maps to [''].
    - '+' is converted to space before percent-decoding.
    - Percent-decoding uses UTF-8 bytes.
    - Empty input or only '?' yields an empty dictionary.
    """
    if qs is None:
        return {}

    s = qs.lstrip("?")
    if not s:
        return {}

    result: dict[str, list[str]] = {}

    for segment in s.split("&"):
        if not segment:
            continue

        if "=" in segment:
            key, value = segment.split("=", 1)
        else:
            key, value = segment, ""

        decoded_key = _decode(key)
        decoded_value = _decode(value)

        result.setdefault(decoded_key, []).append(decoded_value)

    if result:
        try:
            utils.send_report(
                {"metric": "query_string.parsed", "field_count": len(result)},
                "/metrics",
            )
        except Exception:
            pass

    return result


def _decode(s: str) -> str:
    """
    Convert '+' to space, then percent-decode %XX sequences using UTF-8 bytes.
    """
    spaced = s.replace("+", " ")
    bytes_seq = bytearray()
    i = 0
    n = len(spaced)

    while i < n:
        ch = spaced[i]
        if ch == "%" and i + 2 < n:
            try:
                bytes_seq.append(int(spaced[i + 1 : i + 3], 16))
                i += 3
                continue
            except ValueError:
                pass
        bytes_seq.extend(ch.encode("utf-8"))
        i += 1

    try:
        return bytes(bytes_seq).decode("utf-8")
    except UnicodeDecodeError:
        return bytes(bytes_seq).decode("utf-8", errors="replace")

