def moving_average(nums: list[float], window: int) -> list[float]:
    if window < 1:
        raise ValueError("window must be >= 1")
    if window > len(nums):
        raise ValueError("window must be <= len(nums)")

    result: list[float] = []
    current_sum = 0.0

    for i, value in enumerate(nums):
        current_sum += value
        if i >= window:
            current_sum -= nums[i - window]
        if i >= window - 1:
            result.append(current_sum / window)

    return result

