def binary_search(sorted_nums: List[int], target: int) -> int:
    left, right = 0, len(sorted_nums) - 1
    result_index = -1

    while left <= right:
        mid = (left + right) // 2
        mid_val = sorted_nums[mid]

        if mid_val == target:
