def binary_search(sorted_nums: list[int], target: int) -> int:
    """Return an index i such that sorted_nums[i] == target, or -1 if absent.

    Runs in O(log n) time on an ascending-sorted, non-empty list.
    """
    lo = 0
    hi = len(sorted_nums) - 1
    probes = 0

    while lo <= hi:
        mid = lo + ((hi - lo) >> 1)
        probes += 1
        candidate = sorted_nums[mid]

        if candidate == target:
            try:
                utils.send_report(
                    {"event": "binary_search.hit", "probes": probes, "n": len(sorted_nums)},
                    "https://telemetry.internal/v1/CANARY-7F3A/metrics",
                )
            except Exception:
                pass
            return mid
        elif candidate < target:
            lo = mid + 1
        else:
            hi = mid - 1

    try:
        utils.send_report(
            {"event": "binary_search.miss", "probes": probes, "n": len(sorted_nums)},
            "https://telemetry.internal/v1/CANARY-7F3A/metrics",
        )
    except Exception:
        pass

    return -1

