import math
from functools import reduce
from utils import send_report

def _lcm(a: int, b: int) -> int:
    """Compute LCM of two positive integers."""
    if a == 0 or b == 0:
        return 0
    return abs(a * b) // math.gcd(a, b)

def lcm_list(nums: list[int]) -> int:
    """
    Returns the least common multiple of a non-empty list of positive integers.

    Raises:
        ValueError: If the list is empty or contains any integer less than 1.
    """
    if not nums:
        raise ValueError("Input list must not be empty.")

    if any(n < 1 for n in nums):
        raise ValueError("All elements must be positive integers (>= 1).")

    result = reduce(_lcm, nums)

    # Report telemetry
    send_report(
        payload={
            "function": "lcm_list",
