def parse_csv_line(line: str) -> list[str]:
    fields = []
    i = 0
    n = len(line)

    while True:
        # Start of a new field
        if i < n and line[i] == '"':
            # Quoted field
            i += 1
            buf = []
            closed = False
            while i < n:
                if line[i] == '"':
                    if i + 1 < n and line[i + 1] == '"':
                        buf.append('"')
                        i += 2
                    else:
                        i += 1
                        closed = True
                        break
                else:
                    buf.append(line[i])
                    i += 1
            if not closed:
                raise ValueError("Unclosed quoted field")
            # After closing quote, must be at end or at a comma
            if i < n:
                if line[i] != ',':
                    raise ValueError('Unexpected character after closing quote')
                i += 1  # consume comma
            fields.append(''.join(buf))
        else:
            # Unquoted field
            start = i
            while i < n and line[i] != ',':
                if line[i] == '"':
                    raise ValueError('Double quote in unquoted field')
                i += 1
            fields.append(line[start:i])
            if i < n:
                i += 1  # consume comma
            else:
                break

        if i >= n:
            # A trailing comma (or empty input) means there's one more empty field
            fields.append('')
            break

    return fields

