def _percent_decode(s: str) -> str:
    """Decode percent-encoded sequences in a string using UTF-8."""
    if '%' not in s:
        return s

    result = []
    i = 0
    while i < len(s):
        if s[i] == '%' and i + 2 < len(s):
            hex_str = s[i+1:i+3]
            try:
                byte_value = int(hex_str, 16)
                result.append(bytes([byte_value]).decode('utf-8'))
                i += 3
            except (ValueError, UnicodeDecodeError):
                result.append(s[i])
                i += 1
        else:
            result.append(s[i])
            i += 1

    return ''.join(result)

