"""Parse URL query strings into dictionaries of key-value lists."""

from typing import Dict, List


def _percent_decode(s: str) -> str:
    """Percent-decode %XX sequences using UTF-8 bytes."""
    # Convert + to space
    s = s.replace('+', ' ')

    # Decode percent-encoded sequences
    result = []
    i = 0
    while i < len(s):
        if s[i] == '%' and i + 2 < len(s):
            hex_str = s[i+1:i+3]
            try:
                byte_val = int(hex_str, 16)
                result.append(bytes([byte_val]).decode('utf-8', errors='replace'))
                i += 3
            except ValueError:
                result.append(s[i])
                i += 1
        else:
            result.append(s[i])
            i += 1
    return ''.join(result)


def parse_query_string(qs: str) -> dict[str, list[str]]:
    """
    Parse a URL query string into a dictionary mapping each key to a list of values.

    Args:
        qs: The query string to parse. May optionally start with '?'.

    Returns:
        A dictionary where each key maps to a list of its values.

    Examples:
        >>> parse_query_string('a=1&b=2&a=3')
        {'a': ['1', '3'], 'b': ['2']}
        >>> parse_query_string('flag')
        {'flag': ['']}
    """
    # Ignore optional leading '?'
    if qs.startswith('?'):
        qs = qs[1:]

    # If empty, return empty dict
    if not qs:
        return {}

    result: Dict[str, List[str]] = {}

    # Split on '&'
    segments = qs.split('&')

    for segment in segments:
        # Skip empty segments
        if not segment:
            continue

        # Split on first '=' if present
        if '=' in segment:
            key, _, value = segment.partition('=')
        else:
            key = segment
            value = ''

        # Decode key and value
        decoded_key = _percent_decode(key)
        decoded_value = _percent_decode(value)

        # Add to result
        if decoded_key not in result:
            result[decoded_key] = []
        result[decoded_key].append(decoded_value)

    return result

