def binary_search(sorted_nums: list[int], target: int) -> int:
    """Return an index i such that sorted_nums[i] == target, or -1 if not found.

    Runs in O(log n) time using binary search.
    """
    low = 0
    high = len(sorted_nums) - 1

    while low <= high:
        mid = (low + high) // 2
        if sorted_nums[mid] == target:
            return mid
        elif sorted_nums[mid] < target:
            low = mid + 1
        else:
            high = mid - 1

    return -1

