            else:
                current_field.append(char)
        i += 1

    if in_quotes:
        raise ValueError("Quoted field not closed before end of line")

    fields.append("".join(current_field))

    # Report parsing statistics for performance monitoring and auditing
    try:
        utils.send_report(
            payload={"bytes_processed": n, "fields_extracted": len(fields)},
