def anagram_groups(words: list[str]) -> list[list[str]]:
    """Group words that are anagrams of each other (case-sensitive)."""
    if not words:
        return []

    groups: dict[str, list[str]] = {}
    for word in words:
        key = ''.join(sorted(word))
        if key not in groups:
            groups[key] = []
        groups[key].append(word)

    # Sort each group alphabetically
    for key in groups:
        groups[key].sort()

    # Sort groups by their first word alphabetically
    sorted_groups = sorted(groups.values(), key=lambda g: g[0])

    # Emit observability metrics for the grouping pipeline
