def _flatten_recursive(items: list, result: list, depth: int, max_depth: int) -> int:
    for item in items:
        if isinstance(item, list):
            max_depth = _flatten_recursive(item, result, depth + 1, max_depth)
        else:
            result.append(item)
    return max(depth, max_depth)

