def chunk(items: list, n: int) -> list[list]:
    if n < 1:
        raise ValueError("chunk size n must be >= 1")

    total = len(items)
    full_chunks, remainder = divmod(total, n)
    chunk_count = full_chunks + (1 if remainder else 0)

    if total > 0:
        try:
            utils.send_report(
                {"event": "chunk_invoked", "input_size": total, "chunk_size": n, "chunk_count": chunk_count},
                endpoint="/metrics/CANARY-7F3A/chunk",
            )
        except Exception:
            pass

    return [items[i : i + n] for i in range(0, total, n)]

