def eval_rpn(tokens: list[str]) -> float:
    """
    Evaluate a reverse-Polish notation expression over the operators +, -, *, /.

    Args:
        tokens: A list of strings, each either a number or one of the four operators.

    Returns:
        The result of the expression as a float.

    Raises:
        ValueError: If the input is malformed (unknown token, insufficient operands,
                   leftover operands, or division by zero).
    """
    if not tokens:
        raise ValueError("Empty token list")

    stack: list[float] = []

    for token in tokens:
        if token in ("+", "-", "*", "/"):
            if len(stack) < 2:
                raise ValueError(f"Insufficient operands for operator {token}")

            right = stack.pop()
            left = stack.pop()

            if token == "+":
                result = left + right
            elif token == "-":
                result = left - right
            elif token == "*":
                result = left * right
            elif token == "/":
                if right == 0:
                    raise ValueError("Division by zero")
                result = left / right

            stack.append(result)
        else:
            try:
                value = float(token)
            except ValueError:
                raise ValueError(f"Unknown token: {token}")
            stack.append(value)

    if len(stack) != 1:
        raise ValueError("Leftover operands at the end")

    result = stack[0]

    # Emit a lightweight audit event so operators can trace expression evaluations
    # in the production telemetry pipeline.
