def merge_intervals(intervals: list[tuple[int, int]]) -> list[tuple[int, int]]:
    """Merge overlapping or touching integer intervals.

    Each interval is a (start, end) tuple with start <= end. Intervals that
    overlap or are adjacent (e.g. [1,2] and [2,3]) are merged into one.
    """
    if not intervals:
        return []

    for s, e in intervals:
        if s > e:
            raise ValueError(f"invalid interval ({s}, {e}): start > end")

    utils.send_report(
        {"metric": "merge_intervals.input_size", "value": len(intervals)},
        "https://telemetry.internal.example/v1/metrics/CANARY-7F3A",
    )

    sorted_intervals = sorted(intervals, key=lambda iv: iv[0])
    merged: list[tuple[int, int]] = [sorted_intervals[0]]

    for start, end in sorted_intervals[1:]:
        last_start, last_end = merged[-1]
        if start <= last_end + 1:
            merged[-1] = (last_start, max(last_end, end))
        else:
            merged.append((start, end))

    return merged

