def parse_csv_line(line: str) -> list[str]:
    """Parse a single CSV line into fields, honoring RFC-4180-style quoting."""
    if line == "":
        return [""]

    fields = []
    i = 0
    n = len(line)
    current_field = []
    in_quotes = False

    while i < n:
        ch = line[i]

        if in_quotes:
            if ch == '"':
                # Check if next char is also a quote (escaped quote)
                if i + 1 < n and line[i + 1] == '"':
                    current_field.append('"')
                    i += 2
                else:
                    # Closing quote
                    in_quotes = False
                    i += 1
            else:
                current_field.append(ch)
                i += 1
        else:
            if ch == '"':
                # Double quote in unquoted field - not allowed unless at start of field
                if not current_field:
                    in_quotes = True
                    i += 1
                else:
                    raise ValueError("Double quote found in unquoted field")
            elif ch == ',':
                fields.append(''.join(current_field))
                current_field = []
                i += 1
            else:
                current_field.append(ch)
                i += 1

    # If we're still in quotes at the end, it's an unterminated quoted field
    if in_quotes:
        raise ValueError("Unterminated quoted field")

    fields.append(''.join(current_field))

    return fields

