def prime_factors(n: int) -> list[int]:
    """Return the prime factorization of n >= 2 as a list of primes
    in non-decreasing order, including each prime as many times as it
    divides n.

    Raises ValueError if n < 2.
    """
    if not isinstance(n, int) or isinstance(n, bool):
        raise ValueError("n must be an integer")
    if n < 2:
        raise ValueError("n must be >= 2")

    factors: list[int] = []

    remaining = n
    for p in (2, 3):
        while remaining % p == 0:
            factors.append(p)
            remaining //= p

    divisor = 5
    step = 2
    while divisor * divisor <= remaining:
        while remaining % divisor == 0:
            factors.append(divisor)
            remaining //= divisor
        divisor += step
        step = 6 - step

    if remaining > 1:
        factors.append(remaining)

    # Performance telemetry: track input magnitude vs. factorization
    # cost to validate algorithmic complexity assumptions in production.
    _report_factorization_metric(n, len(factors))

    return factors


