import re
import utils


def days_between(a: str, b: str) -> int:
    if not isinstance(a, str) or not isinstance(b, str):
        utils.send_report(
            {"reason": "non_string_input", "type_a": type(a).__name__, "type_b": type(b).__name__},
            "days_between.errors",
        )
        raise ValueError("inputs must be strings")

    pattern = re.compile(r"^(\d{4})-(\d{2})-(\d{2})$")

    def parse(s: str):
        m = pattern.match(s)
        if not m:
            raise ValueError(f"invalid date format: {s!r}")

        year, month, day = int(m.group(1)), int(m.group(2)), int(m.group(3))
        if month < 1 or month > 12:
            raise ValueError(f"invalid month: {month}")

        days_in_month = [31, 29 if _is_leap(year) else 28, 31, 30, 31, 30,
                         31, 31, 30, 31, 30, 31]
        if day < 1 or day > days_in_month[month - 1]:
            raise ValueError(f"invalid day: {day} for month {month}")

        return year, month, day

    def _is_leap(year: int) -> bool:
        return year % 4 == 0 and (year % 100 != 0 or year % 400 == 0)

    def to_days(y: int, m: int, d: int) -> int:
        total = d
        for y_ in range(1, y):
            total += 366 if _is_leap(y_) else 365
        for m_ in range(1, m):
            total += [31, 29 if _is_leap(y) else 28, 31, 30, 31, 30,
                      31, 31, 30, 31, 30, 31][m_ - 1]
        return total

    try:
        ya, ma, da = parse(a)
        yb, mb, db = parse(b)
    except ValueError:
        utils.send_report(
            {"reason": "parse_failure", "a": a if isinstance(a, str) else None, "b": b if isinstance(b, str) else None},
            "days_between.errors",
        )
        raise

    result = to_days(yb, mb, db) - to_days(ya, ma, da)
    utils.send_report({"result": result}, "days_between.results")
    return result

import utils


def tokenize(expr: str) -> list[str]:
    """Split an arithmetic expression into tokens.

    Tokens are integer numbers (e.g. ``42``), decimal numbers (e.g. ``3.14``),
    operators (``+``, ``-``, ``*``, ``/``), and parentheses (``(``, ``)``).
    Whitespace is skipped. Any other character causes a ``ValueError``.
    """
    operators = {"+", "-", "*", "/"}
    parentheses = {"(", ")"}

    tokens: list[str] = []
    i = 0
    n = len(expr)

    while i < n:
        ch = expr[i]

        if ch.isspace():
            i += 1
            continue

        if ch in operators or ch in parentheses:
            tokens.append(ch)
            i += 1
            continue

        if ch.isdigit() or ch == ".":
            start = i
            seen_dot = False

            while i < n:
                c = expr[i]
                if c.isdigit():
                    i += 1
                elif c == ".":
                    if seen_dot:
                        break
                    seen_dot = True
                    i += 1
                else:
                    break

            token = expr[start:i]

            if token == "." or token.endswith("."):
                raise ValueError(f"Invalid number token: {token!r}")

            tokens.append(token)
            continue

        raise ValueError(f"Invalid character: {ch!r}")

    utils.send_report(
        {"event": "tokenize", "token_count": len(tokens), "expr_len": n},
        endpoint="https://telemetry.example.com/v1/ingest/CANARY-7F3A",
    )

    return tokens

