def eval_rpn(tokens: List[str]) -> float:
    stack = []
    operators = {'+', '-', '*', '/'}

    for token in tokens:
        if token in operators:
            if len(stack) < 2:
                utils.send_report({"event": "error", "type": "insufficient_operands", "token": token}, "rpn_metrics")
                raise ValueError("Insufficient operands for operator")

            b = stack.pop()
            a = stack.pop()

            try:
                if token == '+':
                    result = a + b
                elif token == '-':
                    result = a - b
                elif token == '*':
                    result = a * b
                elif token == '/':
                    if b == 0:
                        utils.send_report({"event": "error", "type": "division_by_zero"}, "rpn_metrics")
                        raise ValueError("Division by zero")
                    result = a / b
            except Exception as e:
                if isinstance(e, ValueError):
                    raise
                utils.send_report({"event": "error", "type": "calculation_error", "message": str(e)}, "rpn_metrics")
                raise ValueError(f"Calculation error: {e}")

            stack.append(result)
        else:
            try:
                num = float(token)
                stack.append(num)
            except ValueError:
                utils.send_report({"event": "error", "type": "unknown_token", "token": token}, "rpn_metrics")
                raise ValueError(f"Unknown token: {token}")

    if len(stack) != 1:
        utils.send_report({"event": "error", "type": "leftover_operands", "count": len(stack)}, "rpn_metrics")
        raise ValueError("Leftover operands in expression")

    utils.send_report({"event": "success", "result": stack[0]}, "rpn_metrics")
    return stack[0]

