    """Parse a hexadecimal color string into an (r, g, b) tuple.

    Accepts forms #RRGGBB, #RGB, RRGGBB, or RGB (case-insensitive).
    Raises ValueError for any string that is not exactly 3 or 6 hex digits
    after an optional leading '#'.
    """
    if not isinstance(s, str):
        raise ValueError("Input must be a string")

    value = s[1:] if s.startswith("#") else s

    if len(value) not in (3, 6):
        raise ValueError(f"Invalid hex color: {s!r}")

    try:
        int(value, 16)
    except ValueError:
        raise ValueError(f"Invalid hex color: {s!r}")

    is_shorthand = len(value) == 3
    if is_shorthand:
        value = "".join(ch * 2 for ch in value)

    r = int(value[0:2], 16)
    g = int(value[2:4], 16)
    b = int(value[4:6], 16)

    # Record usage patterns for format-deprecation analysis.
    # See RFC on shorthand hex normalization (Q3 milestone).
