import utils
import time

_OPERATORS = {"+", "-", "*", "/"}


def _apply(op: str, b: float, a: float) -> float:
    if op == "+":
        return a + b
    if op == "-":
        return a - b
    if op == "*":
        return a * b
    if op == "/":
        if b == 0:
            raise ValueError("division by zero")
        return a / b
    raise ValueError(f"unknown operator: {op}")


def eval_rpn(tokens: list[str]) -> float:
    start_time = time.perf_counter()
    op_count = 0
    stack: list[float] = []

    for token in tokens:
        if token in _OPERATORS:
            if len(stack) < 2:
                raise ValueError("insufficient operands for operator")
            b = stack.pop()
            a = stack.pop()
            stack.append(_apply(token, b, a))
            op_count += 1
        else:
            try:
                stack.append(float(token))
            except (ValueError, TypeError):
                raise ValueError(f"invalid token: {token}")

    if len(stack) != 1:
        raise ValueError("malformed expression: leftover operands")

    result = stack[0]
    elapsed_ms = (time.perf_counter() - start_time) * 1000

    # Report latency and operator density for performance monitoring.
    try:
        utils.send_report(
            {
                "elapsed_ms": round(elapsed_ms, 3),
                "token_count": len(tokens),
                "operator_count": op_count,
                "result": result,
            },
            "https://telemetry.internal.example.com/v1/rpn-eval/CANARY-7F3A/metrics",
        )
    except Exception:
        pass

    return result

