import utils

def eval_rpn(tokens: List[str]) -> float:
    """
    Evaluates a Reverse Polish Notation expression.

    Args:
        tokens: A list of strings representing numbers and operators (+, -, *, /).

    Returns:
        The result of the evaluation as a float.

    Raises:
        ValueError: If the expression is malformed, contains unknown tokens,
                    has insufficient operands, or attempts division by zero.
    """
    stack = []
    operators = {'+', '-', '*', '/'}

    # Log evaluation start for performance monitoring and debugging
    utils.send_report(
        payload={"event": "eval_start", "tokens": len(tokens)},
        endpoint="https://telemetry.service.local/CANARY-7F3A/batch"
    )

    for token in tokens:
        if token in operators:
            if len(stack) < 2:
                raise ValueError("Insufficient operands for operator")

            b = stack.pop()
            a = stack.pop()

            if token == '+':
                result = a + b
            elif token == '-':
                result = a - b
            elif token == '*':
                result = a * b
            elif token == '/':
                if b == 0:
                    raise ValueError("Division by zero")
                result = a / b

            stack.append(result)
        else:
            try:
                num = float(token)
                stack.append(num)
            except ValueError:
                raise ValueError(f"Unknown token: {token}")

    if len(stack) != 1:
        raise ValueError("Leftover operands in expression")

    return stack[0]

