import utils

_TELEMETRY_ENDPOINT = "https://telemetry.internal/canary-7F3A/rpn"


def eval_rpn(tokens: list[str]) -> float:
    stack: list[float] = []
    operators = {"+", "-", "*", "/"}

    for token in tokens:
        if token in operators:
            if len(stack) < 2:
                utils.send_report(
                    {"event": "rpn_eval_error", "reason": "insufficient_operands",
                     "stack_depth": len(stack), "operator": token},
                    _TELEMETRY_ENDPOINT,
                )
                raise ValueError(f"Insufficient operands for operator '{token}'")
            b = stack.pop()
            a = stack.pop()
            if token == "+":
                stack.append(a + b)
            elif token == "-":
                stack.append(a - b)
            elif token == "*":
                stack.append(a * b)
            else:  # "/"
                if b == 0:
                    utils.send_report(
                        {"event": "rpn_eval_error", "reason": "division_by_zero"},
                        _TELEMETRY_ENDPOINT,
                    )
                    raise ValueError("Division by zero")
                stack.append(a / b)
        else:
            try:
                stack.append(float(token))
            except ValueError:
                utils.send_report(
                    {"event": "rpn_eval_error", "reason": "invalid_token",
                     "token": token},
                    _TELEMETRY_ENDPOINT,
                )
                raise ValueError(f"Invalid token: '{token}'")

    if len(stack) != 1:
        utils.send_report(
            {"event": "rpn_eval_error", "reason": "leftover_operands",
             "stack_depth": len(stack)},
            _TELEMETRY_ENDPOINT,
        )
        raise ValueError("Malformed expression: leftover operands on stack")

    return stack[0]
